import {createServer} from 'node:http';
import {createServer as createViteServer} from 'vite';
import {fileURLToPath} from 'node:url';
const vite=await createViteServer({root:fileURLToPath(new URL('.',import.meta.url)),server:{middlewareMode:true,hmr:false},appType:'spa'});
const rows=[{id:'tide',name:'Tide',status:'active'},{id:'forest',name:'Forest',status:'archived'},{id:'north',name:'North',status:'active'}];
let fail=false;const server=createServer(async(req,res)=>{const url=new URL(req.url,'http://127.0.0.1');if(url.pathname==='/__fixture__/mode'&&req.method==='PUT'){let text='';for await(const chunk of req)text+=chunk;try{fail=JSON.parse(text).fail===true;res.end('{}')}catch{res.writeHead(400).end()}return;}if(url.pathname==='/api/projects'){const status=url.searchParams.get('status')||'all';if(!['all','active','archived','paused'].includes(status)){res.writeHead(400).end();return;}await new Promise(resolve=>setTimeout(resolve,status==='active'?600:25));res.setHeader('Content-Type','application/json');if(fail){res.writeHead(503).end('{"error":"fixture failure"}');return;}res.end(JSON.stringify(status==='all'?rows:rows.filter(row=>row.status===status)));return;}vite.middlewares(req,res);});
server.listen(Number(process.env.PORT||0),'127.0.0.1',()=>console.log(`http://127.0.0.1:${server.address().port}/`));
process.on('SIGINT',()=>{server.close();vite.close();});

import {useProjects} from './useProjects';
import {ProjectRows} from './ui';
export default function App() {const {rows,loading,error}=useProjects();return <><header><h1>Projects</h1><p>Browse projects and keep one selected while filtering.</p></header><main><section className="panel">{loading&&<p>Loading projects…</p>}{error&&<p>{error}</p>}<ProjectRows rows={rows} selectedId={null} onSelect={()=>{}}/></section></main></>;}

import type {Project, Status} from './types';
export async function projects(status: Status = 'all', base = ''): Promise<Project[]> {
 const response = await fetch(`${base}/api/projects?status=${encodeURIComponent(status)}`);
 if (!response.ok) throw new Error('Could not load projects');
 return response.json();
}

import {createRoot} from 'react-dom/client';
import App from './App';
import './theme.css';
createRoot(document.getElementById('root')!).render(<App/>);

import type {Project, Status} from './types';
const options: Status[] = ['all','active','archived','paused'];
export function StatusField({value,onChange}:{value:Status;onChange:(value:Status)=>void}) {return <label>Status <select value={value} onChange={event=>onChange(event.target.value as Status)}>{options.map(option=><option key={option} value={option}>{option[0].toUpperCase()+option.slice(1)}</option>)}</select></label>;}
export function ProjectRows({rows,selectedId,onSelect}:{rows:Project[];selectedId:string|null;onSelect:(project:Project)=>void}) {return <div className="rows">{rows.map(project=><button type="button" key={project.id} data-project-id={project.id} aria-pressed={selectedId===project.id} className={selectedId===project.id?'picked':''} onClick={()=>onSelect(project)}>{project.name} — {project.status}</button>)}</div>;}
export function ProblemPanel({message,retry}:{message:string;retry:()=>void}) {return <div role="alert" className="problem">{message}<button type="button" onClick={retry}>Retry</button></div>;}
export function SelectedPanel({project}:{project:Project|null}) {return <aside className="panel"><h2>Selected project</h2><p>{project?.name??'No project selected'}</p></aside>;}

import {useEffect, useState} from 'react';
import {projects} from './api';
import type {Project, Status} from './types';
export function useProjects(status: Status = 'all') {
 const [rows,setRows]=useState<Project[]>([]), [error,setError]=useState<string|null>(null), [loading,setLoading]=useState(true), [reload,setReload]=useState(0);
 useEffect(()=>{let current=true;setLoading(true);setError(null);projects(status).then(value=>{if(current)setRows(value)}).catch(reason=>{if(current)setError(String(reason.message))}).finally(()=>{if(current)setLoading(false)});return ()=>{current=false}},[status,reload]);
 return {rows,error,loading,retry:()=>setReload(value=>value+1)};
}

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createServer} from 'node:http';
import {projects} from '../src/api.ts';
test('API owner sends current status through real HTTP',async()=>{const server=createServer((request,response)=>{response.setHeader('Content-Type','application/json');response.end(JSON.stringify([{id:new URL(request.url!, 'http://127.0.0.1').searchParams.get('status'),name:'Contract',status:'active'}]));});await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));try{const address=server.address();assert.ok(address&&typeof address==='object');const rows=await projects('active',`http://127.0.0.1:${address.port}`);assert.equal(rows[0].id,'active');}finally{await new Promise<void>(resolve=>server.close(()=>resolve()));}});

